package dev.saffron;

import java.util.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.security.*;
import org.springframework.stereotype.Component;
import org.springframework.core.env.Environment;
import org.springframework.mail.javamail.JavaMailSenderImpl;
import jakarta.mail.internet.MimeMessage;
import jakarta.mail.MessagingException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import nl.martijndwars.webpush.*;

@Component class ChannelGateway {
 final Environment env;private final Map<String,String> modes;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();
 private final String base,key,origin;private final boolean local;private NativePush push;
 record Result(String state,String reference,String error,boolean expired){}
 static class NativePush extends PushService {
  NativePush(String pub,String priv,String subject)throws GeneralSecurityException{super(pub,priv,subject);}
  NativePush(KeyPair pair){super(pair,"mailto:operator@example.invalid");}
  nl.martijndwars.webpush.HttpRequest prepare(String endpoint,String pub,String auth,byte[] body)throws Exception{return prepareRequest(new Notification(endpoint,pub,auth,body),Encoding.AES128GCM);}
 }
 ChannelGateway(Environment env)throws Exception{this.env=env;local=env.getProperty("app.allow-insecure-local",Boolean.class,false);origin=env.getRequiredProperty("app.origin");base=env.getProperty("channels.local-base","http://localhost:8608");key=env.getProperty("channels.local-key","");modes=Map.of("EMAIL",env.getProperty("channels.email-mode","disabled"),"SMS",env.getProperty("channels.sms-mode","disabled"),"PUSH",env.getProperty("channels.push-mode","disabled"));
  if(java.security.Security.getProvider("BC")==null)java.security.Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());
  for(var entry:modes.entrySet()){String allowed=switch(entry.getKey()){case "EMAIL"->"smtp";case "SMS"->"twilio";default->"webpush";};if(!Set.of("disabled","local",allowed).contains(entry.getValue()))throw new IllegalArgumentException("Unsupported channel mode");}
  if(modes.containsValue("local")){URI uri=URI.create(base);if(!local||!"http".equals(uri.getScheme())||!Set.of("localhost","127.0.0.1").contains(uri.getHost())||uri.getUserInfo()!=null||uri.getQuery()!=null||key.length()<32)throw new IllegalStateException("Local channel simulation requires explicit local mode, loopback and a fixture key");}
  if(mode("EMAIL").equals("smtp")){required("smtp-host");required("smtp-user");required("smtp-password");email(required("smtp-from"));int port=env.getProperty("channels.smtp-port",Integer.class,587);if(port<1||port>65535)throw new IllegalArgumentException("Invalid SMTP port");}
  if(mode("SMS").equals("twilio")){if(!required("twilio-sid").matches("AC[a-fA-F0-9]{32}"))throw new IllegalArgumentException("Invalid Twilio account");required("twilio-token");phone(required("twilio-from"));}
  if(mode("PUSH").equals("webpush")){String subject=required("vapid-subject");if(!subject.matches("mailto:[^\\s]+@[^\\s]+")&&!subject.startsWith("https://"))throw new IllegalArgumentException("VAPID contact required");push=new NativePush(required("vapid-public"),required("vapid-private"),subject);}
 }
 private String required(String name){String value=env.getProperty("channels."+name,"");if(value.isBlank())throw new IllegalStateException("Missing channel configuration: "+name);return value;}
 String mode(String channel){if(!modes.containsKey(channel))throw new IllegalArgumentException("Unknown notification channel");return modes.get(channel);}
 String vapidPublic(){return mode("PUSH").equals("webpush")?env.getProperty("channels.vapid-public",""):"";}
 static String email(String value){if(value==null||value.length()>254||!value.matches("[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}"))throw new IllegalArgumentException("Valid single email address required");return value;}
 static String phone(String value){if(value==null||!value.matches("\\+[1-9][0-9]{7,14}"))throw new IllegalArgumentException("E.164 phone number required");return value;}
 static void pushEndpoint(String endpoint){URI uri=URI.create(endpoint);if(endpoint.length()>2048||!"https".equals(uri.getScheme())||!Set.of("fcm.googleapis.com","updates.push.services.mozilla.com","web.push.apple.com").contains(uri.getHost())||uri.getUserInfo()!=null||(uri.getPort()!=-1&&uri.getPort()!=443)||uri.getFragment()!=null||uri.getQuery()!=null||uri.getPath().length()<2)throw new IllegalArgumentException("Untrusted push endpoint");}
 static void pushKeys(String pub,String auth)throws Exception{if(Base64.getUrlDecoder().decode(pub).length!=65||Base64.getUrlDecoder().decode(auth).length!=16)throw new IllegalArgumentException("Invalid push keys");Utils.loadPublicKey(pub);}
 private HttpResponse<byte[]> request(java.net.http.HttpRequest req)throws Exception{var pending=http.sendAsync(req,info->new RoadRouter.LimitedBody());try{return pending.get(3500,java.util.concurrent.TimeUnit.MILLISECONDS);}finally{if(!pending.isDone())pending.cancel(true);}}
 private JsonNode json(byte[] raw){return JsonMapper.builder().build().readTree(raw);}
 Result send(Map<String,Object> job){String channel=job.get("channel").toString(),mode=job.get("mode").toString(),id=job.get("id").toString();try{
  if(mode.equals("local")){var payload=Map.of("channel",channel,"destination",job.get("destination"),"title","Saffron update","body",job.get("title"),"href",origin+job.get("href"));var response=request(java.net.http.HttpRequest.newBuilder(URI.create(base+"/v1/deliveries")).timeout(Duration.ofSeconds(3)).header("Authorization","Bearer "+key).header("Idempotency-Key",id).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(JsonMapper.builder().build().writeValueAsString(payload))).build());return response(response,true);}
  if(mode.equals("smtp")){var mail=new JavaMailSenderImpl();mail.setHost(required("smtp-host"));mail.setPort(env.getProperty("channels.smtp-port",Integer.class,587));mail.setUsername(required("smtp-user"));mail.setPassword(required("smtp-password"));var props=mail.getJavaMailProperties();for(String p:List.of("mail.smtp.auth","mail.smtp.starttls.enable","mail.smtp.starttls.required","mail.smtp.ssl.checkserveridentity"))props.put(p,"true");for(String p:List.of("mail.smtp.connectiontimeout","mail.smtp.timeout","mail.smtp.writetimeout"))props.put(p,"3000");MimeMessage message=new MimeMessage(mail.getSession()){@Override protected void updateMessageID()throws MessagingException{setHeader("Message-ID","<"+id+"@saffron.notifications>");}};message.setFrom(required("smtp-from"));message.setRecipients(jakarta.mail.Message.RecipientType.TO,email(job.get("destination").toString()));message.setSubject("Saffron update","UTF-8");message.setText(job.get("title")+"\nSign in to view: "+origin+job.get("href"),"UTF-8");mail.send(message);return new Result("ACCEPTED",id,null,false);}
  if(mode.equals("twilio")){String data="To="+encode(job.get("destination").toString())+"&From="+encode(required("twilio-from"))+"&Body="+encode(job.get("title")+". Sign in: "+origin+job.get("href"));var response=request(java.net.http.HttpRequest.newBuilder(URI.create("https://api.twilio.com/2010-04-01/Accounts/"+required("twilio-sid")+"/Messages.json")).timeout(Duration.ofSeconds(3)).header("Authorization",twilioAuth()).header("Content-Type","application/x-www-form-urlencoded").POST(java.net.http.HttpRequest.BodyPublishers.ofString(data)).build());if(response.statusCode()==429)return new Result("RETRY",null,"Provider rate limit",false);if(response.statusCode()>=500)return unknown();if(response.statusCode()>=400)return new Result("FAILED",null,"Provider rejected message",false);return twilio(json(response.body()));}
  if(mode.equals("webpush")){pushEndpoint(job.get("destination").toString());JsonNode subscription=json(job.get("subscription").toString().getBytes(StandardCharsets.UTF_8));byte[] payload=JsonMapper.builder().build().writeValueAsBytes(Map.of("id",id,"title","Saffron update","body","You have a new Saffron update. Sign in to view it.","href",job.get("href")));var prepared=push.prepare(job.get("destination").toString(),subscription.path("p256dh").asString(),subscription.path("auth").asString(),payload);var builder=java.net.http.HttpRequest.newBuilder(URI.create(prepared.getUrl())).timeout(Duration.ofSeconds(3));prepared.getHeaders().forEach(builder::header);var response=request(builder.POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(prepared.getBody())).build());int status=response.statusCode();if(status==404||status==410)return new Result("FAILED",null,"Push subscription expired",true);if(status==429)return new Result("RETRY",null,"Push rate limit",false);if(status>=500)return unknown();if(status<200||status>=300)return new Result("FAILED",null,"Push service rejected message",false);return new Result("ACCEPTED",id,null,false);}
  return new Result("FAILED",null,"Channel mode unavailable",false);
 }catch(Exception error){if(error instanceof InterruptedException)Thread.currentThread().interrupt();return mode.equals("local")?new Result("RETRY",null,"Simulator outcome uncertain; retry uses original key",false):unknown();}}
 private static String encode(String text){return URLEncoder.encode(text,StandardCharsets.UTF_8);}
 private String twilioAuth(){return "Basic "+Base64.getEncoder().encodeToString((required("twilio-sid")+":"+required("twilio-token")).getBytes(StandardCharsets.UTF_8));}
 private static Result unknown(){return new Result("UNKNOWN",null,"Provider outcome unresolved; automatic resend disabled",false);}
 private Result response(HttpResponse<byte[]> response,boolean local){int status=response.statusCode();if(status==409)return unknown();if(status==429||status>=500)return new Result("RETRY",null,"Provider unavailable",false);if(status>=400)return new Result("FAILED",null,"Provider rejected message",status==410);var node=json(response.body());String state=node.path("state").asString();if(!Set.of("ACCEPTED","DELIVERED","FAILED").contains(state)||!node.path("id").asString().matches("sim_[a-f0-9]{32}"))throw new IllegalArgumentException("Invalid provider receipt");return new Result(state,node.path("id").asString(),null,false);}
 static Result twilio(JsonNode node){String sid=node.path("sid").asString();if(!sid.matches("SM[a-fA-F0-9]{32}"))throw new IllegalArgumentException("Invalid provider reference");String state=switch(node.path("status").asString()){case "delivered","read"->"DELIVERED";case "failed","undelivered","canceled"->"FAILED";default->"ACCEPTED";};return new Result(state,sid,null,false);}
 Result poll(Map<String,Object> job){try{String ref=job.get("provider_id").toString();if(job.get("mode").equals("local")){if(!ref.matches("sim_[a-f0-9]{32}"))return unknown();return response(request(java.net.http.HttpRequest.newBuilder(URI.create(base+"/v1/deliveries/"+ref)).timeout(Duration.ofSeconds(3)).header("Authorization","Bearer "+key).GET().build()),true);}if(job.get("mode").equals("twilio")){if(!ref.matches("SM[a-fA-F0-9]{32}"))return unknown();var response=request(java.net.http.HttpRequest.newBuilder(URI.create("https://api.twilio.com/2010-04-01/Accounts/"+required("twilio-sid")+"/Messages/"+ref+".json")).timeout(Duration.ofSeconds(3)).header("Authorization",twilioAuth()).GET().build());if(response.statusCode()!=200)return new Result("ACCEPTED",ref,"Status lookup unavailable",false);return twilio(json(response.body()));}return new Result("ACCEPTED",ref,null,false);}catch(Exception e){return new Result("ACCEPTED",job.get("provider_id").toString(),"Status lookup unavailable",false);}}
 JsonNode localMessage(String reference)throws Exception{if(!reference.matches("sim_[a-f0-9]{32}"))throw new IllegalArgumentException("Invalid simulator reference");var response=request(java.net.http.HttpRequest.newBuilder(URI.create(base+"/v1/deliveries/"+reference)).timeout(Duration.ofSeconds(3)).header("Authorization","Bearer "+key).GET().build());if(response.statusCode()!=200)throw new IllegalStateException("Simulator mailbox unavailable");return json(response.body()).path("payload");}
}
